import json
d = (_items[0].get('json', {}) if _items else {}).get('dossier', {})
if not d:
    return [{'json': {'markdown': '# Error\nNo dossier data found.'}}]

ident = d.get('identity', {})
pro = d.get('professional', {})
soc = d.get('social', {})
br = d.get('breach', {})
pd = d.get('personal', {})

lines = [
    '# SPOTTER Dossier — ' + (ident.get('name') or 'Unknown'),
    '',
    '## Identity',
    '| Field | Value |',
    '|---|---|',
    '| Username | `' + (ident.get('username') or '') + '` |',
    '| Email | ' + (ident.get('email') or '') + ' |',
    '| SID | `' + (ident.get('sid') or '') + '` |',
    '| Enabled | ' + str(ident.get('enabled', '?')) + ' |',
    '| Admin | ' + str(ident.get('is_admin', '?')) + ' |',
    '',
]

if pro.get('specialty') or pro.get('job_title') or pro.get('employer'):
    lines += ['## Professional', '| Field | Value |', '|---|---|']
    if pro.get('specialty'):      lines.append('| Specialty | **' + pro['specialty'] + '** |')
    if pro.get('job_title'):      lines.append('| Title | ' + pro['job_title'] + ' |')
    if pro.get('employer'):       lines.append('| Employer | ' + pro['employer'] + ' |')
    if pro.get('office_address'): lines.append('| Office | ' + pro['office_address'] + ' |')
    lines.append('')
    wh = pro.get('work_history') or []
    if wh:
        lines += ['### Work History', '| Title | Employer | From | To |', '|---|---|---|---|']
        for w in wh:
            lines.append('| ' + (w.get('title') or '?') + ' | ' + (w.get('employer') or '?') +
                         ' | ' + (w.get('start_date') or '?') + ' | ' + (w.get('end_date') or 'present') + ' |')
        lines.append('')

emails = pd.get('emails') or ([ident.get('email')] if ident.get('email') else [])
phones = pd.get('phones') or []
full_name = ' '.join(x for x in [pd.get('first_name'), pd.get('middle_name'), pd.get('last_name')] if x)
locs = pd.get('locations_lived') or []
addrs = pd.get('addresses') or []

if full_name or emails or phones or pd.get('location') or addrs or locs:
    lines += ['## Personal Data', '| Field | Value |', '|---|---|']
    if full_name: lines.append('| Full name | ' + full_name + ' |')
    for em in emails: lines.append('| Email | ' + em + ' |')
    for ph in phones: lines.append('| Phone | ' + ph + ' |')
    if pd.get('location'): lines.append('| Location | ' + pd['location'] + ' |')
    for addr in addrs:
        av = addr if isinstance(addr, str) else ', '.join(v for v in addr.values() if v)
        lines.append('| Address | ' + av + ' |')
    if locs: lines.append('| Locations lived | ' + '; '.join(locs) + ' |')
    lines.append('')

if soc.get('linkedin') or soc.get('twitter') or soc.get('github') or soc.get('other'):
    lines += ['## Online Presence']
    if soc.get('linkedin'): lines.append('- LinkedIn: ' + soc['linkedin'])
    if soc.get('twitter'):  lines.append('- Twitter/X: ' + soc['twitter'])
    if soc.get('github'):   lines.append('- GitHub: ' + soc['github'])
    for p in (soc.get('other') or []):
        plat = (p.get('platform') or 'Other').title()
        uname = (' (' + p['username'] + ')') if p.get('username') else ''
        lines.append('- ' + plat + ': ' + (p.get('url') or '?') + uname)
    lines.append('')

if (br.get('total') or 0) > 0 or br.get('has_stealer_log'):
    lines += ['## Flare.io Breach Data', '| Field | Value |', '|---|---|']
    lines.append('| Total events | ' + str(br.get('total', 0)) + ' |')
    sl_val = 'YES — exfiltration likely' if br.get('has_stealer_log') else 'No'
    lines.append('| Stealer log | ' + sl_val + ' |')
    if br.get('last_seen'): lines.append('| Last seen | ' + str(br['last_seen']) + ' |')
    try:
        bsumm = json.loads(br.get('summary') or '{}')
        for k, v in bsumm.items():
            lines.append('| ' + k.replace('_', ' ').title() + ' | ' + str(v) + ' |')
    except Exception:
        pass
    all_creds = list(br.get('leaked_credentials') or []) + list(br.get('stealer_logs') or []) + list(br.get('paste_exposures') or [])
    if all_creds:
        # The credential column appears only when the caller asked to unmask.
        show_cred = bool(br.get('credentials_included'))
        head = '| Type | Source | Identity | Domain | Pw Exposed |'
        rule = '|---|---|---|---|---|'
        if show_cred:
            head = '| Type | Source | Identity | Domain | Pw Exposed | Credential |'
            rule = '|---|---|---|---|---|---|'
        lines += ['', '### Breach Records', head, rule]
        for b in all_creds[:20]:
            pw = 'Yes' if b.get('password_exposed') else 'No'
            row = ('| ' + (b.get('event_type') or '?') + ' | ' + (b.get('source') or '?') +
                   ' | ' + (b.get('identity_name') or '?') + ' | ' + (b.get('domain') or '?') + ' | ' + pw + ' |')
            if show_cred:
                cv = str(b.get('credential_value') or '')
                row += ' `' + cv.replace('|', '\\|') + '` |' if cv else ' — |'
            lines.append(row)
    elif (br.get('total') or 0) > 0:
        de = br.get('domain_exposure') or {}
        if de.get('domain'):
            lines += ['', '_Counts come from the ' + str(de['domain']) + ' domain-wide Flare sweep; '
                      'per-record detail for this person has not been ingested yet._']
        else:
            lines += ['', '_Summary counts only — no per-record breach detail in the graph._']
    lines.append('')

if d.get('alert'):
    lines += ['## Alert', '> **' + str(d['alert']) + '**', '']

if d.get('beacons'):
    # Framework-neutral: this table carries Brute Ratel badgers too, and the old
    # hard-coded 'Cobalt Strike Beacons' heading mislabelled every one of them.
    _FW = {'cobalt_strike': 'Cobalt Strike', 'brute_ratel': 'Brute Ratel'}
    lines += ['## C2 Sessions', '| Framework | Hostname | IP | Last Check-in | Admin |', '|---|---|---|---|---|']
    for b in d['beacons']:
        _fw = str(b.get('c2_framework') or '').strip().lower()
        _fwl = _FW.get(_fw) or (_fw.replace('_', ' ').title() if _fw else '?')
        # is_admin is three-state. `str(x or '?')` rendered a confirmed False as
        # '?', erasing the difference between "not privileged" and "we never
        # learned" -- the one distinction an operator reads this column for.
        _adm = b.get('is_admin')
        _adm = '?' if _adm is None or _adm == '' else ('Yes' if str(_adm).strip().lower() in ('true', '1', 'yes') else 'No')
        lines.append('| ' + _fwl + ' | ' + (b.get('hostname') or '?') + ' | ' + (b.get('internal_ip') or '?') +
                     ' | ' + str(b.get('last_checkin') or '?') + ' | ' + _adm + ' |')
    lines.append('')

if d.get('ad', {}).get('permissions'):
    lines += ['## AD Permissions', '| Target | Right | Score |', '|---|---|---|']
    for p in d['ad']['permissions'][:10]:
        lines.append('| ' + (p.get('target') or '?') + ' | ' + (p.get('right') or '?') + ' | ' + str(p.get('score') or '?') + ' |')
    lines.append('')

if d.get('ad', {}).get('groups'):
    lines += ['## Group Memberships'] + ['- ' + g for g in d['ad']['groups'] if g] + ['']

if d.get('ad', {}).get('sessions'):
    lines += ['## Active Sessions', '| Computer | Is DC |', '|---|---|']
    for s in d['ad']['sessions']:
        lines.append('| ' + (s.get('computer') or '?') + ' | ' + str(s.get('is_dc') or '?') + ' |')
    lines.append('')

if d.get('tech_stack'):
    lines += ['## Tech Stack'] + ['- ' + t for t in d['tech_stack']] + ['']

flowsint_url = d.get('flowsint_url', '')
lines += ['---', '*Generated by SPOTTER | Flowsint: ' + flowsint_url + '*']
return [{'json': {'markdown': chr(10).join(lines)}}]
